INSERT INTO public.recetas (id, nombre, categoria, descripcion, rendimiento_cantidad, rendimiento_unidad, unidades_por_pack, nombre_pack, porcentaje_gastos_extras, costo_mano_obra_lote, margen_objetivo_porcentaje, precio_venta_unidad, precio_venta_pack, precio_venta_lote, tiempo_preparacion_min, tiempo_horneado_min, temperatura_horno_c, metodo_coccion, notas_chefcita, color_tag, favorita, costo_incompleto)
VALUES
  ('d01ce000-0000-4000-9000-000000000001', 'Mini pie', 'Tartas y Pies', 'Registro del 11 de noviembre: 4 unidades elaboradas a $3.000 c/u (hasta $12.000 si se venden las 4). Tiempo: 2 horas.', 4, 'mini pies', 1, 'Unidad', 0, 0, 60, 3000, 3000, 12000, 120, 0, 0, 'Horno', 'DATOS: Masa $5,42/g; Relleno $1.507/100 g ($15,07/g); Huevo $200/50 g ($4/g); Alulosa $6.890/500 g ($13,78/g); Merengue rinde ~20 mini pies; Empaque $50/u (4 u = $200); Tiempo 2 h. FALTA DATO: gramos de masa y relleno por unidad, receta exacta del merengue (y si el lote fue para 4 o 20), valor hora de mano de obra, gas y electricidad.', 'rose', true, true),
  ('d01ce000-0000-4000-9000-000000000002', 'Donas rellenas (Caja x4)', 'Donas', 'Escenario de octubre: caja de 4 donas rellenas. Mano de obra registrada: $4.000 (1 hora) y $200 de relleno por dona.', 4, 'donas', 4, 'Caja x4 rellenas', 0, 4000, 60, 0, 0, 0, 60, 0, 0, 'Horno', 'DATOS (octubre): 4 rellenos × $200 = $800; Mano de obra 1 hora = $4.000 ($1.000/dona si el lote es de 4); Se consultó aumentar 10 g de alulosa. FALTA DATO: masa e ingredientes de las 4 donas, costo de la caja/empaque y precio definitivo de venta.', 'amber', true, true),
  ('d01ce000-0000-4000-9000-000000000003', 'Donas (Caja x5)', 'Donas', 'Escenario de octubre: caja de 5 donas. Mano de obra registrada: $4.000 (1 hora). Si todas son rellenas, $1.000 en rellenos.', 5, 'donas', 5, 'Caja x5', 0, 4000, 60, 0, 0, 0, 60, 0, 0, 'Horno', 'DATOS (octubre): 5 rellenos si todas son rellenas = $1.000 ($200 c/u); Mano de obra 1 hora = $4.000; Aumento de alulosa consultado: 10 g. FALTA DATO: confirmar si todas llevan relleno, ingredientes de las donas, costo de caja y precio de venta.', 'amber', false, true),
  ('d01ce000-0000-4000-9000-000000000004', 'Bizcocho con manjar y coco (Reg. A · 12 u)', 'Bizcochos', 'Registro A (8 de octubre): producción de 12 unidades (10 vendidas a $400 = $4.000 cobrados, 2 sin vender).', 12, 'unidades', 1, 'Unidad', 0, 0, 60, 400, 400, 4800, 30, 0, 0, 'Horno', 'DATOS (8 oct, Registro A): 12 unidades producidas, 10 vendidas, 2 sin vender, precio $400/u, ingresos cobrados $4.000. DUDA: confirmar si es receta diferente al Registro B (20 u a $500) o actualización de precio. FALTA DATO: ingredientes, empaque, mano de obra y costo por unidad.', 'caramel', false, true),
  ('d01ce000-0000-4000-9000-000000000005', 'Bizcocho con manjar y coco (Reg. B · 20 u)', 'Bizcochos', 'Registro B (8 de octubre): 401 g bizcocho + 301 g manjar + 200 g coco (902 g totales) para 20 unidades de 30 g a $500 c/u.', 20, 'unidades', 1, 'Unidad', 0, 0, 60, 500, 500, 10000, 30, 0, 0, 'Horno', 'DATOS (8 oct, Registro B): 401 g bizcocho + 301 g manjar + 200 g coco = 902 g totales; rendimiento informado: 20 u de 30 g; precio $500/u (ingreso potencial $10.000). INCONSISTENCIA: 20 u × 30 g = 600 g (quedan 302 g sin explicar). FALTA DATO: precios de bizcocho, manjar, coco, empaque y mano de obra.', 'caramel', true, true),
  ('d01ce000-0000-4000-9000-000000000006', 'Postre de bizcocho y crema pastelera', 'Postres', 'Rinde 12 porciones en 1 hora. Precio normal: $4.500/porción (promoción de inauguración en noviembre: $3.500/porción).', 12, 'porciones', 1, 'Porción', 0, 0, 60, 4500, 4500, 54000, 60, 0, 0, 'Horno', 'DATOS: 12 porciones; 1 hora; Precio normal $4.500 ($54.000 las 12); Promo todo noviembre $3.500 ($42.000 las 12, dcto $1.000 = 22,22%). Crema pastelera se prepara con agua y leche líquida; se usa para remojo y bizcocho. FALTA DATO: gramos y precios de bizcocho, crema pastelera, leche líquida, remojo, empaque y mano de obra.', 'rose', true, true),
  ('d01ce000-0000-4000-9000-000000000007', 'Masa de tarta', 'Masas y Bases', 'Base calculada con harina ($720/kg), mantequilla ($2.950/250 g) y alulosa ($6.890/500 g). Costo unitario registrado: $5,42/g.', 100, 'gramos', 100, '100 g', 0, 0, 60, 0, 0, 0, 30, 0, 0, 'Horno', 'DATO registrado: $5,42/g (5 g=$27,10 | 10 g=$54,20 | 15 g=$81,30 | 20 g=$108,40 | 25 g=$135,50 | 30 g=$162,60 | 40 g=$216,80 | 50 g=$271 | 100 g=$542). Usada en Mini pie. FALTA DATO: receta con gramos exactos de harina, mantequilla y alulosa para recalcularlo y comprobarlo.', 'caramel', false, true),
  ('d01ce000-0000-4000-9000-000000000008', 'Merengue', 'Masas y Bases', 'Registro del 11 de noviembre para mini pie. Rendimiento aproximado: 20 mini pies (usa huevo y alulosa).', 20, 'mini pies', 1, 'Porción mini pie', 0, 0, 60, 0, 0, 0, 20, 0, 0, 'Batido', 'DATOS (11 nov): rinde aprox. 20 mini pies; insumos mencionados: huevo ($200/50 g = $4/g) y alulosa ($6.890/500 g = $13,78/g). FALTA DATO: gramos exactos de la receta y confirmar si se preparó para los 4 mini pies o para 20.', 'rose', false, true),
  ('d01ce000-0000-4000-9000-000000000009', 'Receta comparación azúcar / alulosa (Grupo x5)', 'Dulces', 'Consulta de noviembre sobre reemplazo de 80 g de alulosa ($1.102,40) por 80 g de azúcar ($104) y mano de obra de $4.000.', 5, 'unidades', 5, 'Grupo x5', 0, 4000, 60, 0, 0, 0, 30, 0, 0, 'Horno', 'DATOS (nov): 80 g alulosa ($1.102,40 a $6.890/500 g) vs 80 g azúcar ($104 a $1.300/kg) = diferencia $998,40 en endulzante; mano de obra consultada $4.000; incremento consultado 100%; presentación en grupos de 5 unidades. FALTA DATO: nombre del producto, resto de ingredientes, rendimiento total y precio definitivo.', 'caramel', false, true),
  ('d01ce000-0000-4000-9000-000000000010', 'Torta sin azúcar (Tamaño 20)', 'Tortas', 'Conversación del 15 de noviembre: tamaño 20. Peso de bizcocho aclarado a 220 g (600 g iniciales correspondían a bizcocho + remojo).', 1, 'torta', 1, 'Tamaño 20', 0, 0, 60, 0, 0, 0, 60, 0, 0, 'Horno', 'DATOS (15 nov): Tamaño 20; 220 g bizcocho aclarados vs 600 g bizcocho más remojo; recargos consultados 100% (costo ×2, margen 50%) y 200% (costo ×3, margen 66,67%). FALTA DATO: confirmar si 20 es cm de diámetro, ingredientes de bizcocho, remojo, relleno, cobertura, empaque, mano de obra y precio de venta.', 'rose', false, true),
  ('d01ce000-0000-4000-9000-000000000011', 'Torta sin azúcar (Tamaño 25)', 'Tortas', 'Conversación del 15 de noviembre: tamaño 25. Se consultaron recargos sobre costo del 100% y 200%.', 1, 'torta', 1, 'Tamaño 25', 0, 0, 60, 0, 0, 0, 60, 0, 0, 'Horno', 'DATOS (15 nov): Tamaño 25; referencia de 220 g bizcocho vs 600 g bizcocho más remojo; recargos consultados 100% y 200%. FALTA DATO: confirmar si 25 es cm de diámetro, ingredientes completos, remojo, relleno, cobertura, empaque, mano de obra y precio de venta.', 'rose', false, true),
  ('d01ce000-0000-4000-9000-000000000012', 'Soletillas', 'Masas y Bases', 'Registro del 11 de noviembre: receta recalculada a partir de 256 g de claras, 149 g de yemas y 15 g de vainilla.', 1, 'lote', 1, 'Lote', 0, 0, 60, 0, 0, 0, 30, 0, 0, 'Horno', 'DATOS (11 nov): 256 g claras, 149 g yemas, 15 g vainilla. FALTA DATO: demás ingredientes de la receta original, rendimiento en unidades, costos de claras/yemas/vainilla y precio de venta.', 'amber', false, true),
  ('d01ce000-0000-4000-9000-000000000013', 'Mousse de limón sin azúcar', 'Postres', 'Producto mencionado en conversación del 22 de octubre.', 1, 'lote', 1, 'Lote', 0, 0, 60, 0, 0, 0, 30, 0, 0, 'Refrigerado', 'DATO (22 oct): solo se recuperó el nombre. FALTA DATO: receta completa, cantidades, rendimiento, costos y precio de venta.', 'amber', false, true),
  ('d01ce000-0000-4000-9000-000000000014', 'Preparación de limón y huevo', 'Masas y Bases', 'Consulta del 1 de noviembre: preparación con 4 limones y huevos.', 1, 'lote', 1, 'Lote', 0, 0, 60, 0, 0, 0, 30, 0, 0, 'Olla', 'DATO (1 nov): 4 limones y huevos. FALTA DATO: nombre definitivo, cantidad de huevos, demás ingredientes, rendimiento, costos y precio de venta.', 'amber', false, true)
